      busy: await read($, scanning), problem: await read($, error), now: Date.now(),
      onRescan: () => scanSoon($, 'config'),
      onFlip: id => void update($, cfgOpen, cur => toggle(cur, id)),
      onPick: id => {
        void update($, cfgItem, cur => (cur === id ? '' : id))
        void update($, cfgPage, () => 0)
      },
      onRaw: () => void update($, cfgRaw, v => !v),
      onPage: delta => void update($, cfgPage, p => Math.max(0, p + delta)),
      onQuery: v => void update($, cfgQuery, () => v),
    })
  })

  // ------------------------------------------------------------------ HISTORY
  on('ui.render', { component: 'Pane', requestId: PANES.history.id }, async ($, e) => {
    const { Box, Text, Markdown } = $.ui.resolve(e)
    await read($, tick)
    const { out } = await loadConfig($)
