        {await header($, e, data?.generated)}
        {data?.history_md ? (
          <Markdown text={data.history_md} />
        ) : (
          <Text>No history yet: press Rescan (reads docs/HISTORY.md).</Text>
        )}
      </Box>
    )
  })
}

